mapper.select:
select  from dish_template_change_requests r
left join merchants m on m.id=r.merchant_id left join dish_templates t on t.id=r.template_id
where r.id=#{requestId}

select  from dish_template_change_requests r
left join merchants m on m.id=r.merchant_id left join dish_templates t on t.id=r.template_id
where r.id=#{requestId} and r.merchant_id=#{merchantId}

select count(*) from dish_template_change_requests r left join dish_templates t on t.id=r.template_id
where r.merchant_id=#{merchantId}
and r.status=#{status}
and t.name like concat('%',#{keyword},'%')

select  from dish_template_change_requests r
left join merchants m on m.id=r.merchant_id left join dish_templates t on t.id=r.template_id
where r.merchant_id=#{merchantId}
and r.status=#{status}
and t.name like concat('%',#{keyword},'%')
order by r.submitted_at desc,r.id desc limit #{offset},#{pageSize}
